enum {ID_a,ID_b,ID_sum,ID_diff};enum {ID_add,ID_sub};void op_add();void op_sub();uint32_t a_consumers[2] = {ID_add,ID_sub};uint32_t b_consumers[2] = {ID_add,ID_sub};uint32_t sum_producers[1] = {ID_add};uint32_t diff_producers[1] = {ID_sub};uint32_t add_inputs[2] = {ID_a,ID_b};uint32_t add_outputs[1] = {ID_sum};uint32_t sub_inputs[2] = {ID_a,ID_b};uint32_t sub_outputs[1] = {ID_diff};Variable variables[] = {{NULL,0,a_consumers,2,I32},{NULL,0,b_consumers,2,I32},{sum_producers,1,NULL,0,I32},{diff_producers,1,NULL,0,I32},};Operation operations[] = {{add_inputs,2,add_outputs,1,op_add,Host},{sub_inputs,2,sub_outputs,1,op_sub,Cuda},};uint32_t inputs[2] = {ID_a,ID_b};uint32_t outputs[2] = {ID_diff,ID_sum};Model model = {.variables = variables,.n_variables = 4,.operations = operations,.n_operations = 2,.inputs = inputs,.n_inputs = 2,.outputs = outputs,.n_outputs = 2,};void c_add(i32,i32,i32*);void c_sub(i32,i32,i32*);void op_add(){struct {i32 a;i32 b;i32 sum;} ctx;request(ID_a, &ctx.a);request(ID_b, &ctx.b);c_add(ctx.a,ctx.b,&ctx.sum);submit(ID_sum, &ctx.sum);}void op_sub(){struct {i32 a;i32 b;i32 diff;} ctx;request(ID_a, &ctx.a);request(ID_b, &ctx.b);c_sub(ctx.a,ctx.b,&ctx.diff);submit(ID_diff, &ctx.diff);}int main(){ launch(); }